// Des: Tests for plain-word commands
// Flo: parse phrases > check job + slot > unknown words > every rule names a real job
// I/O: phrases (constants) > pass/fail
// Run: cd E:\zz-base-home\as-apps\in-inte\or-orac-webs && mise exec -- zig build test -Dfile=ru-reci-main-test.zig
// ===================================================================
const std = @import("std"); const reci = @import("ru-reci-main.zig"); const jobs = @import("ru-jobs-tabl.zig");
fn parse(aren: std.mem.Allocator, text: []const u8) !reci.Cmd { return (try reci.parse(aren, text)) orelse error.TestUnexpectedResult; }
test "open takes a url or path in the url slot" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const pge = try parse(aren.allocator(), "Open /compute/instances"); try std.testing.expectEqualStrings("page-open", pge.job); try std.testing.expectEqualStrings("/compute/instances", pge.args.url); }
test "account, data, money and help phrases" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); try std.testing.expectEqualStrings("signup", (try parse(al, "sign up")).job); try std.testing.expectEqualStrings("login", (try parse(al, "log in")).job); try std.testing.expectEqualStrings("logout", (try parse(al, "Log out")).job); const ver = try parse(al, "verify https://x.co/a"); try std.testing.expectEqualStrings("verify-email", ver.job); try std.testing.expectEqualStrings("https://x.co/a", ver.args.url); try std.testing.expectEqualStrings("usage-view", (try parse(al, "show usage")).job); try std.testing.expectEqualStrings("plan-view", (try parse(al, "show plan")).job); const inv = try parse(al, "invite bob@example.com"); try std.testing.expectEqualStrings("user-invite", inv.job); try std.testing.expectEqualStrings("bob@example.com", inv.args.to); const docs = try parse(al, "docs always free limits"); try std.testing.expectEqualStrings("always free limits", docs.args.text); }
test "resource phrases carry the name in the title slot" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); const stp = try parse(al, "Stop instance ci-box"); try std.testing.expectEqualStrings("inst-stop", stp.job); try std.testing.expectEqualStrings("ci-box", stp.args.title); try std.testing.expectEqualStrings("inst-list", (try parse(al, "show instances")).job); try std.testing.expectEqualStrings("metrics-view", (try parse(al, "show cpu of ci-box")).job); try std.testing.expectEqualStrings("secl-view", (try parse(al, "show open ports of ci-vcn")).job); }
test "unknown words are not understood; every rule names a real job" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); try std.testing.expect((try reci.parse(aren.allocator(), "tell me a joke")) == null); for (reci.RULES) |rul| try std.testing.expect(jobs.find(rul.job) != null); }
